"""Sequential real-contact CPU samples, no GPU/display-FPS claim."""
from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/contact-flux';html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready')
 rows=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,V=INK.VFX,out=[];function run(id,guard,warm){A.start(id,'ryu','training','classic',44);G.paused=false;document.getElementById('dummy').value=guard?'guard':'idle';A.teleport(0,540);A.teleport(1,700);const m=A.moves[id].find(m=>m.category==='special'&&m.strength===0&&!m.air&&!m.throw&&!m.kind.includes('projectile')&&m.damage>0);A.tryMove(0,m?.id||'sMP');let seen=false;const times=[];for(let i=0;i<100;i++){const start=performance.now();A.step();A.render();V.render(G,1);const elapsed=performance.now()-start;if(V.trails.live.some(r=>r?.contactOnly)){seen=true;times.push(elapsed);}if(times.length>=24||seen&&!V.trails.live.some(r=>r?.contactOnly))break;}times.sort((a,b)=>a-b);if(!warm)out.push({character:id,result:guard?'block':'hit',move:m?.id||'sMP',contactFrames:times.length,mean:times.length?times.reduce((s,v)=>s+v,0)/times.length:null,p95:times.length?times[Math.floor(times.length*.95)]:null});}run('ryu',false,true);for(const id of INK.Schema.CHARACTERS)for(const guard of [false,true])run(id,guard,false);return out;}''');b.close()
report={'htmlSha256':hashlib.sha256(html).hexdigest(),'scope':'Sequential special-contact simulation plus full SVG/VFX DOM render, including held contact frames; one warmup. CPU only.','rows':rows,'errors':errors};(O/'frame-cost.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2));assert not errors and all(r['contactFrames']>0 for r in rows)
